import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"React Hook Arguments Convention","description":"","frontmatter":{"id":"4031218897","title":"React Hook Arguments Convention","state":"Approved","created":"2022-12-30T00:00:00.000Z","tags":["react","react-hooks"],"category":"JavaScript"},"headers":[],"relativePath":"adrs/4031218897/README.md","filePath":"adrs/4031218897/README.md"}'),s={name:"adrs/4031218897/README.md"};function i(r,e,l,c,u,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="react-hook-arguments-convention" tabindex="-1">React Hook Arguments Convention <a class="header-anchor" href="#react-hook-arguments-convention" aria-label="Permalink to &quot;React Hook Arguments Convention&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><h3 id="positioned-arguments-vs-single-argument" tabindex="-1">Positioned Arguments vs. Single Argument <a class="header-anchor" href="#positioned-arguments-vs-single-argument" aria-label="Permalink to &quot;Positioned Arguments vs. Single Argument&quot;">​</a></h3><p>Positioned arguments, meaning <code>function (arg1, arg2, arg3)</code>, suffer from the problem that they don’t have names when you use them as a caller, working only for simple situations with one or maybe two arguments.</p><p>Having one or two arguments is rarely the case, and even that, needs clarification. For example, given the following hook calling <code>useFetchPerson(arg1, arg2)</code>, you can not tell what is what by just looking at the shape vs. <code>useFetchPerson({firstName: &quot;&quot;, lastName: &quot;&quot;})</code> having an object brings more clarity because the keys have names.</p><p>Objects allow you to avoid breaking changes since you can always add new keys without removing or renaming the old ones in the worst case and without having to refactor so much all over the place.</p><p>When you are inside the hook (unless you have a destructuring assignment due to default values), having a single variable that lets you know what values are static is beneficial since the cognitive load to figure out what are computed values and what is pass-thru is lower if you see <code>props.[name of something]</code> you can assume it is a static value, which is passed to your hook. Knowing that you will need to look up outside the hook if you have an issue or want to see where the value comes from is straightforward.</p><h3 id="naming-the-argument" tabindex="-1">Naming the argument <a class="header-anchor" href="#naming-the-argument" aria-label="Permalink to &quot;Naming the argument&quot;">​</a></h3><p>Since, by convention, in a React Component, you call the single argument <code>props</code>, and in a React codebase, you will enter and leave the React context, it is better to keep the single argument named <code>props</code> in a hook as well. The <code>props</code> name is generic enough that it still makes sense, and it keeps the clarity around the React codebase, which is the static value that comes from a single argument.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> use a single argument in React Hooks.</li><li>You <strong>MUST</strong> call the single argument <code>props</code>.</li></ul>',11)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
